<script setup lang="ts">
import {ref,onMounted} from 'vue';
import {ElButton,ElCard,ElDialog,ElEmpty,ElMessage,ElMessageBox,ElPagination,ElRadioGroup,ElRadioButton,ElTag} from 'element-plus';
import BusinessPageHeader from '#/components/BusinessPageHeader.vue';
import DataErrorBanner from '#/components/data-state/DataErrorBanner.vue';
import {requestClient} from '#/api/request';
type Comment={id:string;content:string;status:number;nickname:string;workTitle:string;create_time:string};
const rows=ref<Comment[]>([]),status=ref(0),page=ref(1),total=ref(0),loading=ref(false),busy=ref(''),error=ref(''),selected=ref<Comment|null>(null),detail=ref(false);
const labels=['待审核','已公开','已隐藏'];let sequence=0;
async function load(){const seq=++sequence;loading.value=true;error.value='';try{const r=await requestClient.get('/admin/comments',{params:{page:page.value,status:status.value}});if(seq!==sequence)return;rows.value=r.records;total.value=Number(r.total)}catch{if(seq===sequence){rows.value=[];total.value=0;error.value='审核队列加载失败，请重试。'}}finally{if(seq===sequence)loading.value=false}}
function filter(){page.value=1;load()}
async function review(row:Comment,next:number){if(busy.value)return;try{await ElMessageBox.confirm(next===1?'通过后其他用户可以看到这条评论。':'隐藏后仅评论作者可查看原文与状态。',next===1?'通过评论':'隐藏评论',{type:next===1?'info':'warning'});busy.value=row.id;await requestClient.post('/admin/comments/'+row.id+'/review',{status:next,expectedStatus:row.status});detail.value=false;ElMessage.success('审核结果已保存');await load();if(!rows.value.length&&page.value>1){page.value--;await load()}}catch{}finally{busy.value=''}}
onMounted(load);
</script>
<template><div class="review-page"><BusinessPageHeader title="留暖评论审核" description="先阅读，再决定。保护表达的空间，也守住社区边界。" :loading="loading" @refresh="load"/><div class="review-guide"><span class="guide-mark">01 — 03</span><div><strong>阅读内容 → 判断公开范围 → 保存结果</strong><p>新评论通过后才公开；作者可查看自己的审核状态并撤回。审核操作会留痕。</p></div></div><ElCard shadow="never"><div class="review-toolbar"><ElRadioGroup v-model="status" :disabled="!!busy" @change="filter"><ElRadioButton v-for="(label,i) in labels" :key="i" :value="i">{{label}}</ElRadioButton></ElRadioGroup><span>{{loading?'正在读取…':total+' 条评论'}}</span></div><DataErrorBanner v-if="error" :error="error" :retrying="loading" @retry="load"/><div v-loading="loading" class="review-list"><ElEmpty v-if="!rows.length&&!loading&&!error" :description="status===0?'当前没有待审核评论':'此分类暂无评论'"/><article v-for="row in rows" :key="row.id" class="review-item"><div class="item-meta"><span class="avatar">{{row.nickname?.slice(0,1)||'同'}}</span><div><strong>{{row.nickname}}</strong><p>{{row.workTitle||'原作品已不可用'}} · {{String(row.create_time).replace('T',' ').slice(0,16)}}</p></div><ElTag :type="row.status===0?'warning':row.status===1?'success':'info'">{{labels[row.status]}}</ElTag></div><p class="comment-body">{{row.content}}</p><div class="item-actions"><ElButton link type="primary" @click="selected=row;detail=true">展开全文</ElButton><div><ElButton v-if="row.status!==2" :disabled="!!busy" @click="review(row,2)">隐藏</ElButton><ElButton v-if="row.status!==1" type="primary" :loading="busy===row.id" :disabled="!!busy" @click="review(row,1)">通过并公开</ElButton></div></div></article></div><ElPagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next,total" :disabled="loading||!!busy" @current-change="load"/></ElCard><p class="review-foot">本系统不能替代专业心理咨询</p><ElDialog v-model="detail" title="评论全文" width="min(640px,94vw)"><template v-if="selected"><ElTag>{{labels[selected.status]}}</ElTag><p class="full-content">{{selected.content}}</p><p>所属作品：{{selected.workTitle||'已不可用'}}</p></template></ElDialog></div></template>
<style scoped>.review-page{padding:24px;max-width:1240px;margin:auto}.review-guide{display:flex;align-items:center;gap:24px;padding:24px;margin-bottom:24px;border:1px solid var(--el-border-color);background:var(--el-color-primary-light-9);border-radius:18px}.guide-mark{color:var(--el-color-primary);font-size:22px;white-space:nowrap}.review-guide p,.item-meta p{font-size:13px;color:var(--el-text-color-regular);margin:8px 0 0;line-height:1.7}.review-toolbar,.item-actions{display:flex;justify-content:space-between;align-items:center;gap:16px}.review-toolbar{flex-wrap:wrap;margin-bottom:24px}.review-toolbar>span{font-size:13px;color:var(--el-text-color-regular)}.review-list{min-height:160px}.review-item{padding:24px;border:1px solid var(--el-border-color-light);border-radius:16px;margin-bottom:16px}.item-meta{display:flex;gap:12px;align-items:center}.item-meta>div{flex:1;min-width:0}.avatar{display:grid;place-items:center;width:40px;height:40px;border-radius:12px;background:var(--el-color-primary-light-9);color:var(--el-color-primary)}.comment-body{line-height:1.9;white-space:pre-wrap;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;margin:20px 0;color:var(--el-text-color-primary)}.item-actions{border-top:1px solid var(--el-border-color-lighter);padding-top:16px}.full-content{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.9}.review-foot{text-align:center;color:var(--el-text-color-regular);font-size:12px;margin-top:24px}.review-list :deep(.el-empty__description p){font-size:13px;color:var(--el-text-color-regular)}@media(max-width:600px){.review-page{padding:16px}.review-guide{align-items:flex-start;padding:18px;gap:12px}.guide-mark{font-size:14px}.review-item{padding:16px}.item-meta{flex-wrap:wrap}}</style>
